72	     *             on error
73	     */
74	    public synchronized void loadChildren(DBRProgressMonitor monitor, OWNER owner, @Nullable final OBJECT forObject) throws DBException {
75	        if (monitor.isForceCacheUsage() || monitor.isCanceled() ||
76	            (forObject == null && this.childrenCached) ||
77	            (forObject != null && (!forObject.isPersisted() || isChildrenCached(forObject)))) {
78	            return;
79	        }
80	        if (forObject == null) {
81	            // If we have some child objects read before that - do not clear them.
82	            // We have to reuse them because there could be some references in cached model
83	            //clearChildrenCache(null);
84	            super.loadObjects(monitor, owner);
85	        }
86	
87	        DBPDataSource dataSource = owner.getDataSource();
88	        if (dataSource == null) {
89	            throw new DBException(ModelMessages.error_not_connected_to_database);
90	        }
91	        try (JDBCSession session = DBUtils.openMetaSession(monitor, owner, "Load child objects")) {
92	            Map<OBJECT, List<CHILD>> objectMap = new HashMap<>();
93	
94	            // Load columns
95	            try (JDBCStatement dbStat = prepareChildrenStatement(session, owner, forObject)) {
96	                dbStat.setFetchSize(DBConstants.METADATA_FETCH_SIZE);
97	                dbStat.executeStatement();
98	                JDBCResultSet dbResult = dbStat.getResultSet();
99	                if (dbResult != null) {
100	                    try {
101	                        while (dbResult.next()) {
102	                            if (monitor.isCanceled()) {
103	                                return;
104	                            }
105	                            OBJECT object = forObject;
106	                            if (object == null) {
